WITH nyc_taxi_trips AS (SELECT DISTINCT payment_method FROM stg_nyc_taxi_trips WHERE payment_method IS NOT NULL), ecommerce_orders AS (SELECT DISTINCT 'Credit Card' AS payment_type FROM stg_ecommerce_orders WHERE order_id IS NOT NULL) SELECT payment_method AS payment_type, CASE WHEN payment_method = 1 THEN 'Credit Card' WHEN payment_method = 2 THEN 'Cash' WHEN payment_method = 3 THEN 'No Charge' WHEN payment_method = 4 THEN 'Dispute' WHEN payment_method = 5 THEN 'Unknown' ELSE 'Other' END AS payment_type_description FROM nyc_taxi_trips UNION ALL SELECT payment_type, payment_type AS payment_type_description FROM ecommerce_orders LIMIT 100